from __future__ import annotations

OPTION = "legacyResourceId name parentLegacyId hasChildren childrenPropertyIds"
PROPERTY = (
    "legacyResourceId name type isRequired allowEdit measurementUnits parentLegacyId hint "
    "settings { from to step } "
    "hiddenWhen { propertyLegacyId optionLegacyIds } "
    f"options {{ {OPTION} }}"
)
CATEGORY = (
    "legacyResourceId name path hasChildren hasAutogeneratedTitle isPhotoRequiredOnCreate isPriceRequired "
    "freeLimit warningMessage"
)

CATEGORIES = (
    "query Categories { categories(scope: CREATE_AD) { "
    f"{CATEGORY} children {{ {CATEGORY} children {{ {CATEGORY} children {{ {CATEGORY} }} }} }} "
    "} }"
)
CATEGORY_NODE = (
    "query Category($id: ID!) { node(id: $id) { ... on Category { "
    f"{CATEGORY} properties {{ {PROPERTY} }} "
    "} } }"
)
PROPERTY_OPTIONS = (
    "query PropertyOptions($p: ID!) { propertyOptions(parentLegacyId: $p) { "
    f"{OPTION} propertyLegacyId "
    "} }"
)
REGIONS = "query Regions { regions(scope: ALL) { legacyResourceId name default } }"
CONTACT_TYPES = "query ContactTypes { formElements { contactTypes { enum name default } } }"

LOGIN = (
    "mutation LoginUser($accessToken: String!) { "
    "loginUser(accessToken: $accessToken) { entity errors { code message path } } "
    "}"
)
CURRENT_USER = (
    "query CurrentUser { currentUser { "
    "id legacyId name email phone authenticationPhone isShop isPhoneConfirmed isBanned shop { name } "
    "} }"
)

AD_FIELDS = (
    "id legacyResourceId title status statusMessage rejectReason path price expiresAt updatedAt "
    "photo(source: DESKTOP) { url }"
)
AD = f"query Ad($id: ID!) {{ ad(legacyId: $id) {{ {AD_FIELDS} isAuthor }} }}"
MY_ADS = (
    "query MyAds($status: CurrentUserAdStatusEnum, $first: Int, $after: String) { "
    "currentUserAds(status: $status, first: $first, after: $after) { "
    f"totalCount pageInfo {{ hasNextPage endCursor }} nodes {{ {AD_FIELDS} }} "
    "} }"
)

ERRORS = "errors { code message path extensions { code } }"
CREATE_AD = (
    "mutation CreateAd($p: CreateAdAttributes!) { "
    f"createAd(adParams: $p) {{ entity {{ {AD_FIELDS} }} {ERRORS} }} "
    "}"
)
UPDATE_AD = (
    "mutation UpdateAd($id: ID!, $source: SourceEnum!, $p: UpdateAdAttributes!) { "
    f"updateAd(adId: $id, source: $source, adParams: $p) {{ entity {{ {AD_FIELDS} }} {ERRORS} }} "
    "}"
)
DELETE_REASONS = (
    "query DeleteReasons($id: ID!) { ad(legacyId: $id) { deleteReasons { id name descriptionRequired } } }"
)
DESTROY_AD = (
    "mutation DestroyAd($id: ID!, $reason: ID!, $source: SourceEnum!) { "
    f"destroyAd(adId: $id, deleteReasonId: $reason, source: $source) {{ entity {ERRORS} }} "
    "}"
)
PROLONG_ADS = f"mutation ProlongAds($ids: [ID!]!) {{ prolongAds(adIds: $ids) {{ entity {ERRORS} }} }}"
